/*
 * @lc app=leetcode.cn id=15 lang=cpp
 * @lcpr version=30204
 *
 * [15] 三数之和
 */


// @lcpr-template-start
using namespace std;
#include <algorithm>
#include <array>
#include <bitset>
#include <climits>
#include <deque>
#include <functional>
#include <iostream>
#include <list>
#include <queue>
#include <stack>
#include <tuple>
#include <unordered_map>
#include <unordered_set>
#include <utility>
#include <vector>
// @lcpr-template-end
// @lc code=start
class Solution {
public:
    vector<vector<int>> threeSum(vector<int>& nums) {
        set<vector<int>> ans;
        if(nums.size()<3) ans;
        int n=nums.size();
        unordered_map<int,int> mp;
        for (int num : nums) {
            mp[num]++;
        }
        for(auto it=mp.begin();it!=mp.end();++it){
        }
        for(auto it=mp.begin();it!=mp.end();++it){
            for(auto itt=std::next(it);itt!=mp.end();++itt){
                int t=-(it->first+itt->first);
                int c=(t==it->first||t==itt->first);
                auto ittt=mp.find(t);
                if(ittt==mp.end()||ittt->second<=c) continue;
                vector<int> a={it->first,itt->first,t};
                sort(a.begin(),a.end());
                if(ans.find(a)==ans.end())   ans.insert(a);
            }
        }
        if(mp[0]>=3) ans.insert({0,0,0});
        return vector<vector<int>>(ans.begin(),ans.end());
    }
};
// @lc code=end



